module freq_div(
    input CLK_in, input RST,
    output reg CLK_50, output reg CLK_10, output reg CLK_1
);
    reg [3:0] cnt_100;
    reg [6:0] cnt_1000;
    // Divide the input clock signal by 2.
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end
    // Divide the input clock signal by 10.
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_10 <= 1'b0;
            cnt_100 <= 4'b0;
        end else begin
            if (cnt_100 == 4'd9) begin
                CLK_10 <= ~CLK_10;
                cnt_100 <= 4'b0;
            end else begin
                cnt_100 <= cnt_100 + 1;
            end
        end
    end
    // Divide the input clock signal by 100.
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_1 <= 1'b0;
            cnt_1000 <= 7'b0;
        end else begin
            if (cnt_1000 == 7'd99) begin
                CLK_1 <= ~CLK_1;
                cnt_1000 <= 7'b0;
            end else begin
                cnt_1000 <= cnt_1000 + 1;
            end
        end
    end
endmodule
